import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

ct3d_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_s1_forward(torch::Tensor x,
                                          torch::Tensor w,
                                          c10::optional<torch::Tensor> b,
                                          int stride_d, int stride_h, int stride_w,
                                          int pad_d, int pad_h, int pad_w,
                                          int outpad_d, int outpad_h, int outpad_w,
                                          int groups);
"""

ct3d_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Tiled row-slab form for ConvTranspose3d with stride == 1, dilation == 1.
// One CTA owns a TILE_W-wide output row for one (od, oh), all COUT channels,
// and a pair of batch entries (register blocking over N). Each thread keeps
// two accumulators per output channel so every weight load feeds two FMAs,
// halving the dominant per-FMA global weight traffic. The input halos for
// both batch entries are staged in shared memory with float2-interleaved
// layout so the paired activations are fetched with one 64-bit smem load.
template <int COUT, int TILE_W>
__global__ void conv_transpose3d_s1_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    int N, int Cin,
    int D, int H, int Wd,
    int Kd, int Kh, int Kw,
    int Dout, int Hout, int Wout,
    int pad_d, int pad_h, int pad_w)
{
  constexpr int CI_CHUNK = (COUT >= 32 ? 2 : 4);
  constexpr int NB = 2;
  const int tid = threadIdx.x;
  const int slab = blockIdx.z;
  const int npair = slab / Dout;
  const int od = slab - npair * Dout;
  const int n0 = npair * NB;
  const bool has_b1 = (n0 + 1) < N;
  const int oh = blockIdx.y;
  const int ow0 = blockIdx.x * TILE_W;
  const int ow = ow0 + tid;
  const bool valid_p = (ow < Wout);
  const int Ksp = Kd * Kh * Kw;
  const int SXW = TILE_W + Kw - 1;
  const int64_t sXn = (int64_t)Cin * D * H * Wd;
  const int64_t sXc = (int64_t)D * H * Wd;
  const int64_t sXd = (int64_t)H * Wd;
  const int64_t sXh = (int64_t)Wd;
  const int64_t sYn = (int64_t)COUT * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  const int64_t sWci = (int64_t)COUT * Ksp;
  const int64_t sWco = (int64_t)Ksp;
  const int64_t sWkd = (int64_t)Kh * Kw;
  const int64_t sWkh = (int64_t)Kw;
  Tensor mX0 = make_tensor(
      make_gmem_ptr(X + (int64_t)n0 * sXn),
      make_shape(Cin, D, H, Wd),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );
  Tensor mX1 = make_tensor(
      make_gmem_ptr(X + (int64_t)(has_b1 ? (n0 + 1) : n0) * sXn),
      make_shape(Cin, D, H, Wd),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );
  Tensor mY0 = make_tensor(
      make_gmem_ptr(Y + (int64_t)n0 * sYn),
      make_shape(Int<COUT>{}, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );
  Tensor mY1 = make_tensor(
      make_gmem_ptr(Y + (int64_t)(has_b1 ? (n0 + 1) : n0) * sYn),
      make_shape(Int<COUT>{}, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );
  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Int<COUT>{}, Kd, Kh, Kw),
      make_stride(sWci, sWco, sWkd, sWkh, Int<1>{})
  );
  extern __shared__ float smem_raw[];
  float* sX_raw = smem_raw;
  Tensor sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(Int<CI_CHUNK>{}, SXW, Int<NB>{}),
      make_stride(SXW * NB, Int<NB>{}, Int<1>{})
  );
  const int KW4 = (Kw + 3) & ~3;
  float* sW = sX_raw + (size_t)CI_CHUNK * (size_t)SXW * NB;
  float acc0[COUT];
  float acc1[COUT];
  #pragma unroll
  for (int co = 0; co < COUT; ++co) {
    const float bv = (B != nullptr) ? (float)B[co] : 0.0f;
    acc0[co] = bv;
    acc1[co] = bv;
  }
  for (int ci0 = 0; ci0 < Cin; ci0 += CI_CHUNK) {
    for (int kd = 0; kd < Kd; ++kd) {
      const int id = od + pad_d - kd;
      const bool vd = ((unsigned)id < (unsigned)D);
      for (int kh = 0; kh < Kh; ++kh) {
        const int ih = oh + pad_h - kh;
        const bool row_valid = vd && ((unsigned)ih < (unsigned)H);
        const int iw_lo = ow0 + pad_w - (Kw - 1);
        const int x_total = CI_CHUNK * SXW;
        for (int idx = tid; idx < x_total; idx += blockDim.x) {
          int ci_l = idx / SXW;
          int off = idx - ci_l * SXW;
          int ci = ci0 + ci_l;
          int iw = iw_lo + off;
          bool ok = row_valid && (ci < Cin) && ((unsigned)iw < (unsigned)Wd);
          float xv0 = ok ? (float)mX0(ci, id, ih, iw) : 0.0f;
          float xv1 = (ok && has_b1) ? (float)mX1(ci, id, ih, iw) : 0.0f;
          *reinterpret_cast<float2*>(&sX(ci_l, off, 0)) = make_float2(xv0, xv1);
        }
        const int w_total = CI_CHUNK * COUT * KW4;
        for (int idx = tid; idx < w_total; idx += blockDim.x) {
          const int kw_l = idx - (idx / KW4) * KW4;
          const int t2 = idx / KW4;
          const int co_l = t2 - (t2 / COUT) * COUT;
          const int ci_l = t2 / COUT;
          const int ci = ci0 + ci_l;
          sW[idx] = (kw_l < Kw && ci < Cin) ? (float)mW(ci, co_l, kd, kh, kw_l) : 0.0f;
        }
        __syncthreads();
        if (valid_p) {
          const int ow_l = ow - ow0;
          #pragma unroll
          for (int ci_l = 0; ci_l < CI_CHUNK; ++ci_l) {
            const int ci = ci0 + ci_l;
            if (ci >= Cin) break;
            for (int kw4 = 0; kw4 < Kw; kw4 += 4) {
              float2 xv[4];
              #pragma unroll
              for (int t = 0; t < 4; ++t) {
                const int kw = kw4 + t;
                if (kw < Kw) {
                  const int off = ow_l + (Kw - 1) - kw;
                  xv[t] = *reinterpret_cast<const float2*>(&sX(ci_l, off, 0));
                } else {
                  xv[t] = make_float2(0.0f, 0.0f);
                }
              }
              const float* wrow = &sW[(ci_l * COUT) * KW4 + kw4];
              #pragma unroll
              for (int co = 0; co < COUT; ++co) {
                const float4 wv = *reinterpret_cast<const float4*>(wrow + co * KW4);
                acc0[co] += xv[0].x * wv.x;
                acc0[co] += xv[1].x * wv.y;
                acc0[co] += xv[2].x * wv.z;
                acc0[co] += xv[3].x * wv.w;
                acc1[co] += xv[0].y * wv.x;
                acc1[co] += xv[1].y * wv.y;
                acc1[co] += xv[2].y * wv.z;
                acc1[co] += xv[3].y * wv.w;
              }
            }
          }
        }
        __syncthreads();
      }
    }
  }
  if (valid_p) {
    #pragma unroll
    for (int co = 0; co < COUT; ++co) {
      mY0(co, od, oh, ow) = acc0[co];
    }
    if (has_b1) {
      #pragma unroll
      for (int co = 0; co < COUT; ++co) {
        mY1(co, od, oh, ow) = acc1[co];
      }
    }
  }
}
template <int COUT>
static void launch_ct3d(
    const float* X, const float* W, const float* B, float* Y,
    int N, int Cin, int D, int H, int Wd,
    int Kd, int Kh, int Kw,
    int Dout, int Hout, int Wout,
    int pad_d, int pad_h, int pad_w,
    cudaStream_t stream)
{
  constexpr int CI_CHUNK = (COUT >= 32 ? 2 : 4);
  constexpr int NB = 2;
  constexpr int TILE_W = 128;
  const int Ksp = Kd * Kh * Kw;
  const int SXW = TILE_W + Kw - 1;
  dim3 block(TILE_W);
  dim3 grid((unsigned)((Wout + TILE_W - 1) / TILE_W), (unsigned)Hout,
            (unsigned)(Dout * ((N + NB - 1) / NB)));
  const int KW4 = (Kw + 3) & ~3;
  size_t smem = ((size_t)CI_CHUNK * (size_t)SXW * NB + (size_t)CI_CHUNK * (size_t)COUT * (size_t)KW4) * sizeof(float);
  conv_transpose3d_s1_kernel<COUT, TILE_W><<<grid, block, smem, stream>>>(
      X, W, B, Y,
      N, Cin, D, H, Wd,
      Kd, Kh, Kw,
      Dout, Hout, Wout,
      pad_d, pad_h, pad_w
  );
}
torch::Tensor conv_transpose3d_s1_forward(torch::Tensor x,
                                           torch::Tensor w,
                                           c10::optional<torch::Tensor> b,
                                           int stride_d, int stride_h, int stride_w,
                                           int pad_d, int pad_h, int pad_w,
                                           int outpad_d, int outpad_h, int outpad_w,
                                           int groups) {
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  TORCH_CHECK(x.scalar_type() == at::kFloat && w.scalar_type() == at::kFloat,
              "x and w must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cin, Cout/groups, Kd, Kh, Kw]");
  TORCH_CHECK(stride_d == 1 && stride_h == 1 && stride_w == 1,
              "custom kernel currently implements stride == (1,1,1)");
  TORCH_CHECK(outpad_d == 0 && outpad_h == 0 && outpad_w == 0,
              "output_padding must be zero for stride == 1");
  TORCH_CHECK(groups == 1, "custom kernel currently implements groups == 1");
  TORCH_CHECK(pad_d >= 0 && pad_h >= 0 && pad_w >= 0, "padding must be non-negative");
  int64_t N = x.size(0);
  int64_t Cin = x.size(1);
  int64_t D = x.size(2);
  int64_t H = x.size(3);
  int64_t Wd = x.size(4);
  int64_t Kd = w.size(2);
  int64_t Kh = w.size(3);
  int64_t Kw = w.size(4);
  int64_t Co = w.size(1);
  TORCH_CHECK(w.size(0) == Cin, "w.size(0) must equal Cin for groups == 1");
  TORCH_CHECK(Co == 1 || Co == 2 || Co == 4 || Co == 8 || Co == 16 || Co == 32,
              "supported out_channels for the tuned CUTE kernel are {1,2,4,8,16,32}");
  int64_t Dout = (D - 1) * stride_d - 2 * pad_d + Kd + outpad_d;
  int64_t Hout = (H - 1) * stride_h - 2 * pad_h + Kh + outpad_h;
  int64_t Wout = (Wd - 1) * stride_w - 2 * pad_w + Kw + outpad_w;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "invalid transposed-conv output size");
  TORCH_CHECK(((N + 1) / 2) * Dout <= 65535 && Hout <= 65535, "grid dimensions exceed CUDA limits for this kernel");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.is_cuda() && b_c.scalar_type() == at::kFloat, "bias must be CUDA float32");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Co, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Co, Dout, Hout, Wout}, x.options());
  int Ksp = (int)(Kd * Kh * Kw);
  int CI_CHUNK = (Co >= 32 ? 2 : 4);
  const int TILE_W = 128;
  int64_t KW4 = (Kw + 3) & ~3;
  size_t smem = ((size_t)CI_CHUNK * (size_t)(TILE_W + Kw - 1) * 2 + (size_t)CI_CHUNK * (size_t)Co * (size_t)KW4) * sizeof(float);
  TORCH_CHECK(smem <= 48 * 1024, "shared memory tile too large for this configuration");

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  switch ((int)Co) {
    case 1:
      launch_ct3d<1>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr, y.data_ptr<float>(),
                     (int)N, (int)Cin, (int)D, (int)H, (int)Wd,
                     (int)Kd, (int)Kh, (int)Kw,
                     (int)Dout, (int)Hout, (int)Wout,
                     pad_d, pad_h, pad_w, stream);
      break;
    case 2:
      launch_ct3d<2>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr, y.data_ptr<float>(),
                     (int)N, (int)Cin, (int)D, (int)H, (int)Wd,
                     (int)Kd, (int)Kh, (int)Kw,
                     (int)Dout, (int)Hout, (int)Wout,
                     pad_d, pad_h, pad_w, stream);
      break;
    case 4:
      launch_ct3d<4>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr, y.data_ptr<float>(),
                     (int)N, (int)Cin, (int)D, (int)H, (int)Wd,
                     (int)Kd, (int)Kh, (int)Kw,
                     (int)Dout, (int)Hout, (int)Wout,
                     pad_d, pad_h, pad_w, stream);
      break;
    case 8:
      launch_ct3d<8>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr, y.data_ptr<float>(),
                     (int)N, (int)Cin, (int)D, (int)H, (int)Wd,
                     (int)Kd, (int)Kh, (int)Kw,
                     (int)Dout, (int)Hout, (int)Wout,
                     pad_d, pad_h, pad_w, stream);
      break;
    case 16:
      launch_ct3d<16>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr, y.data_ptr<float>(),
                      (int)N, (int)Cin, (int)D, (int)H, (int)Wd,
                      (int)Kd, (int)Kh, (int)Kw,
                      (int)Dout, (int)Hout, (int)Wout,
                      pad_d, pad_h, pad_w, stream);
      break;
    case 32:
      launch_ct3d<32>(x_c.data_ptr<float>(), w_c.data_ptr<float>(), b_ptr, y.data_ptr<float>(),
                      (int)N, (int)Cin, (int)D, (int)H, (int)Wd,
                      (int)Kd, (int)Kh, (int)Kw,
                      (int)Dout, (int)Hout, (int)Wout,
                      pad_d, pad_h, pad_w, stream);
      break;
    default:
      TORCH_CHECK(false, "unreachable Cout dispatch");
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_s1_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

ct3d_ext = load_inline(
    name="cute_conv_transpose3d_s1_ext",
    cpp_sources=ct3d_cpp_decl,
    cuda_sources=ct3d_cuda_src,
    functions=["conv_transpose3d_s1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    ConvTranspose3d backed by a single custom CUTE/CUDA kernel.

    The module keeps an nn.ConvTranspose3d submodule only to preserve parameter
    names/shapes and initialization; forward() never calls PyTorch's convolution.
    The tuned kernel path implements the stride=(1,1,1), dilation=1, groups=1
    case used by this architecture.
    """
    def __init__(self,
                 in_channels: int,
                 out_channels: int,
                 kernel_size: tuple,
                 stride: tuple = (1, 1, 1),
                 padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0),
                 groups: int = 1,
                 bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias
        )
        self._ext = ct3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        s = self.conv_transpose3d.stride
        p = self.conv_transpose3d.padding
        op = self.conv_transpose3d.output_padding
        g = self.conv_transpose3d.groups
        w = self.conv_transpose3d.weight
        b = self.conv_transpose3d.bias
        return self._ext.conv_transpose3d_s1_forward(
            x, w, b if b is not None else None,
            int(s[0]), int(s[1]), int(s[2]),
            int(p[0]), int(p[1]), int(p[2]),
            int(op[0]), int(op[1]), int(op[2]),
            int(g)
        )

