import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

ct3d_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose3d_s1_forward(torch::Tensor x,
                                          torch::Tensor w,
                                          c10::optional<torch::Tensor> b,
                                          int stride_d, int stride_h, int stride_w,
                                          int pad_d, int pad_h, int pad_w,
                                          int outpad_d, int outpad_h, int outpad_w,
                                          int groups);
"""

ct3d_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Tiled row-slab form for ConvTranspose3d with stride == 1, dilation == 1.
// One CTA owns a TILE_W-wide output row for one (od, oh), all COUT channels,
// and a pair of batch entries (register blocking over N). Each thread keeps
// two accumulators per output channel so every weight load feeds two FMAs,
// halving the dominant per-FMA global weight traffic. The input halos for
// both batch entries are staged in shared memory with float2-interleaved
// layout so the paired activations are fetched with one 64-bit smem load.
template <int COUT, int TILE_W>
__global__ void conv_transpose3d_s1_kernel(
    const float* __restrict__ X,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Y,
    int N, int Cin,
    int D, int H, int Wd,
    int Kd, int Kh, int Kw,
    int Dout, int Hout, int Wout,
    int pad_d, int pad_h, int pad_w)
{
  constexpr int CI_CHUNK = (COUT >= 32 ? 2 : 4);
  constexpr int NB = 2;
  const int tid = threadIdx.x;
  const int slab = blockIdx.z;
  const int npair = slab / Dout;
  const int od = slab - npair * Dout;
  const int n0 = npair * NB;
  const bool has_b1 = (n0 + 1) < N;
  const int oh = blockIdx.y;
  const int ow0 = blockIdx.x * TILE_W;
  const int ow = ow0 + tid;
  const bool valid_p = (ow < Wout);
  const int Ksp = Kd * Kh * Kw;
  const int SXW = TILE_W + Kw - 1;
  const int64_t sXn = (int64_t)Cin * D * H * Wd;
  const int64_t sXc = (int64_t)D * H * Wd;
  const int64_t sXd = (int64_t)H * Wd;
  const int64_t sXh = (int64_t)Wd;
  const int64_t sYn = (int64_t)COUT * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  const int64_t sWci = (int64_t)COUT * Ksp;
  const int64_t sWco = (int64_t)Ksp;
  const int64_t sWkd = (int64_t)Kh * Kw;
  const int64_t sWkh = (int64_t)Kw;
  Tensor mX0 = make_tensor(
      make_gmem_ptr(X + (int64_t)n0 * sXn),
      make_shape(Cin, D, H, Wd),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );
  Tensor mX1 = make_tensor(
      make_gmem_ptr(X + (int64_t)(has_b1 ? (n0 + 1) : n0) * sXn),
      make_shape(Cin, D, H, Wd),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );
  Tensor mY0 = make_tensor(
      make_gmem_ptr(Y + (int64_t)n0 * sYn),
      make_shape(Int<COUT>{}, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );
  Tensor mY1 = make_tensor(
      make_gmem_ptr(Y + (int64_t)(has_b1 ? (n0 + 1) : n0) * sYn),
      make_shape(Int<COUT>{}, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );
  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Int<COUT>{}, Kd, Kh, Kw),
      make_stride(sWci, sWco, sWkd, sWkh, Int<1>{})
  );
  extern __shared__ float smem_raw[];
  float* sX_raw = smem_raw;
  Tensor sX = make_tensor(
      make_smem_ptr(sX_raw),
      make_shape(Int<CI_CHUNK>{}, SXW, Int<NB>{}),
      make_stride(SXW * NB, Int<NB>{}, Int<1>{})
  );
  float acc0[COUT];
  float acc1[COUT];
  #pragma unroll
  for (int co = 0; co < COUT; ++co) {
    const float bv = (B != nullptr) ? (float)B[co] : 0.0f;
    acc0[co] = bv;
    acc1[co] = bv;
  }
  for (int ci0 = 0; ci0 < Cin; ci0 += CI_CHUNK) {
    for (int kd = 0; kd < Kd; ++kd) {
      const int id = od + pad_d - kd;
      const bool vd = ((unsigned)id < (unsigned)D);
      for (int kh = 0; kh < Kh; ++kh) {
