                 in_channels: int,
                 out_channels: int,
                 kernel_size: tuple,
                 stride: tuple = (1, 1, 1),
                 padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0),
                 groups: int = 1,
                 bias: bool = False):
