      make_shape(Int<COUT>{}, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );
  Tensor mY1 = make_tensor(
      make_gmem_ptr(Y + (int64_t)(has_b1 ? (n0 + 1) : n0) * sYn),
      make_shape(Int<COUT>{}, Dout, Hout, Wout),
